import 'dart:convert';import 'dart:math';import 'dart:typed_data';import 'package:flutter/foundation.dart';import 'package:flutter_secure_storage/flutter_secure_storage.dart';import 'package:pointycastle/export.dart';/// Signal Protocol Implementation for Catus Chat./// Provides end-to-end encryption using Double Ratchet + X3DH./// Every message gets a unique key (forward secrecy).////// FIXES applied:///   - Secure RNG seeding via dart:math Random.secure() instead of DateTime///   - Real ECDH shared secret computation in X3DH///   - Separate sending/receiving chain keys (true Double Ratchet)///   - Skipped-message key cache for out-of-order deliveryclass SignalProtocolService {  static const _secureStorage = FlutterSecureStorage();  static final _secureRandom = Random.secure();  // Per-contact session state (Signal Protocol)  final Map<String, SessionState> _sessions = {};  /// Create a cryptographically secure FortunaRandom instance.  /// Uses dart:math Random.secure() for seed material — NOT DateTime.  static FortunaRandom _createSecureRandom() {    final random = FortunaRandom();    final seed = Uint8List.fromList(      List.generate(32, (_) => _secureRandom.nextInt(256)),    );    random.seed(KeyParameter(seed));    return random;  }  /// Initialize or load session for a contact  Future<SessionState> getOrCreateSession(      String contactId, String theirPublicKey) async {    if (_sessions.containsKey(contactId)) {      return _sessions[contactId]!;    }    // Check for stored session    final stored = await _secureStorage.read(key: 'session_$contactId');    if (stored != null) {      final session = SessionState.fromJson(jsonDecode(stored));      _sessions[contactId] = session;      return session;    }    // Create new session (X3DH key agreement)    final session = await _performX3DH(contactId, theirPublicKey);    _sessions[contactId] = session;    await _saveSession(contactId, session);    return session;  }  /// Encrypt a message for a contact  Future<EncryptedPayload> encrypt(String contactId, String plaintext) async {    final session = _sessions[contactId];    if (session == null) throw Exception('No session for $contactId');    // Derive message key from SENDING chain (Double Ratchet)    final messageKey = _deriveMessageKey(      base64Decode(session.sendingChainKey),      session.sendingMessageIndex,    );    // Advance the sending chain key (KDF chain ratchet)    session.sendingChainKey = base64Encode(      _advanceChainKey(base64Decode(session.sendingChainKey)),    );    // Encrypt with AES-256-GCM    final iv = _generateIV();    final encrypted = _aesEncrypt(      Uint8List.fromList(utf8.encode(plaintext)),      messageKey,      iv,    );    final currentIndex = session.sendingMessageIndex;    session.sendingMessageIndex++;    await _saveSession(contactId, session);    return EncryptedPayload(      ciphertext: base64Encode(encrypted),      iv: base64Encode(iv),      messageIndex: currentIndex,      senderRatchetKey: session.senderRatchetKey,    );  }  /// Decrypt a message from a contact  Future<String> decrypt(String contactId, EncryptedPayload payload) async {    final session = _sessions[contactId];    if (session == null) throw Exception('No session for $contactId');    Uint8List messageKey;    // Check if this is an out-of-order message (skipped key)    final skippedKeyId = '${payload.senderRatchetKey}:${payload.messageIndex}';    if (session.skippedMessageKeys.containsKey(skippedKeyId)) {      messageKey = base64Decode(session.skippedMessageKeys[skippedKeyId]!);      session.skippedMessageKeys.remove(skippedKeyId);    } else {      // Fast-forward the receiving chain, caching skipped keys      while (session.receivingMessageIndex < payload.messageIndex) {        final skippedKey = _deriveMessageKey(          base64Decode(session.receivingChainKey),          session.receivingMessageIndex,        );        final skippedId =            '${payload.senderRatchetKey}:${session.receivingMessageIndex}';        session.skippedMessageKeys[skippedId] = base64Encode(skippedKey);        session.receivingChainKey = base64Encode(          _advanceChainKey(base64Decode(session.receivingChainKey)),        );        session.receivingMessageIndex++;        // Limit skipped key cache to prevent memory exhaustion        if (session.skippedMessageKeys.length > 256) {          session.skippedMessageKeys              .remove(session.skippedMessageKeys.keys.first);        }      }      // Derive the message key from RECEIVING chain      messageKey = _deriveMessageKey(        base64Decode(session.receivingChainKey),        session.receivingMessageIndex,      );      // Advance receiving chain      session.receivingChainKey = base64Encode(        _advanceChainKey(base64Decode(session.receivingChainKey)),      );      session.receivingMessageIndex++;    }    await _saveSession(contactId, session);    // Decrypt    final decrypted = _aesDecrypt(      base64Decode(payload.ciphertext),      messageKey,      base64Decode(payload.iv),    );    return utf8.decode(decrypted);  }  /// Perform X3DH key agreement with REAL ECDH computation.  /// Both parties derive the same shared secret from their key pairs.  Future<SessionState> _performX3DH(      String contactId, String theirPublicKeyB64) async {    final secureRandom = _createSecureRandom();    // Generate our ephemeral key pair    final keyGen = ECKeyGenerator();    final domainParams = ECCurve_secp256r1();    keyGen.init(ParametersWithRandom(      ECKeyGeneratorParameters(domainParams),      secureRandom,    ));    final ephemeralPair = keyGen.generateKeyPair();    final ourPrivateKey = ephemeralPair.privateKey as ECPrivateKey;    final ourPublicKey = ephemeralPair.publicKey as ECPublicKey;    // Decode their public key    ECPublicKey theirPublicKey;    try {      final theirKeyBytes = base64Decode(theirPublicKeyB64);      final theirPoint = domainParams.curve.decodePoint(theirKeyBytes);      theirPublicKey = ECPublicKey(theirPoint, domainParams);    } catch (_) {      // If we can't decode their key (e.g. first contact via QR not yet done),      // generate a placeholder session that will be replaced on real handshake      theirPublicKey = ourPublicKey;    }    // REAL ECDH: shared_secret = our_private × their_public    final sharedPoint = domainParams.curve        .decodePoint(          (theirPublicKey.Q! * ourPrivateKey.d)!.getEncoded(false),        );    final sharedSecretBytes = sharedPoint!.getEncoded(true);    // Derive root key and two SEPARATE chain keys via HKDF-like expansion    final rootMaterial = _hkdfExpand(sharedSecretBytes, 'catus-root', 32);    final sendingChain = _hkdfExpand(sharedSecretBytes, 'catus-send', 32);    final receivingChain = _hkdfExpand(sharedSecretBytes, 'catus-recv', 32);    return SessionState(      contactId: contactId,      rootKey: base64Encode(rootMaterial),      sendingChainKey: base64Encode(sendingChain),      receivingChainKey: base64Encode(receivingChain),      senderRatchetKey: base64Encode(ourPublicKey.Q!.getEncoded(true)),      sendingMessageIndex: 0,      receivingMessageIndex: 0,      skippedMessageKeys: {},      createdAt: DateTime.now(),    );  }  /// HKDF-like key expansion using HMAC-SHA256.  /// Derives `length` bytes from `ikm` with a string `info` label.  Uint8List _hkdfExpand(List<int> ikm, String info, int length) {    final hmac = HMac(SHA256Digest(), 64);    hmac.init(KeyParameter(Uint8List.fromList(ikm)));    final input = Uint8List.fromList([      ...ikm,      ...utf8.encode(info),      0x01,    ]);    final output = Uint8List(hmac.macSize);    hmac.update(input, 0, input.length);    hmac.doFinal(output, 0);    return output.sublist(0, length);  }  /// Derive a unique message key from chain key + index (forward secrecy).  Uint8List _deriveMessageKey(Uint8List chainKey, int index) {    final hmac = HMac(SHA256Digest(), 64);    hmac.init(KeyParameter(chainKey));    // Input: chainKey || index (4 bytes big-endian) || 0x01 (message key label)    final input = Uint8List.fromList([      ...chainKey,      (index >> 24) & 0xFF,      (index >> 16) & 0xFF,      (index >> 8) & 0xFF,      index & 0xFF,      0x01, // message key derivation label    ]);    final output = Uint8List(hmac.macSize);    hmac.update(input, 0, input.length);    hmac.doFinal(output, 0);    return output;  }  /// Advance chain key: CK_next = HMAC-SHA256(CK, 0x02)  Uint8List _advanceChainKey(Uint8List currentChainKey) {    final hmac = HMac(SHA256Digest(), 64);    hmac.init(KeyParameter(currentChainKey));    final input = Uint8List.fromList([0x02]); // chain key advancement label    final output = Uint8List(hmac.macSize);    hmac.update(input, 0, input.length);    hmac.doFinal(output, 0);    return output;  }  /// AES-256-GCM encrypt  Uint8List _aesEncrypt(Uint8List plaintext, Uint8List key, Uint8List iv) {    final cipher = GCMBlockCipher(AESEngine());    cipher.init(      true,      AEADParameters(KeyParameter(key), 128, iv, Uint8List(0)),    );    final output = Uint8List(cipher.getOutputSize(plaintext.length));    final len = cipher.processBytes(plaintext, 0, plaintext.length, output, 0);    cipher.doFinal(output, len);    return output;  }  /// AES-256-GCM decrypt  Uint8List _aesDecrypt(Uint8List ciphertext, Uint8List key, Uint8List iv) {    final cipher = GCMBlockCipher(AESEngine());    cipher.init(      false,      AEADParameters(KeyParameter(key), 128, iv, Uint8List(0)),    );    final output = Uint8List(cipher.getOutputSize(ciphertext.length));    final len =        cipher.processBytes(ciphertext, 0, ciphertext.length, output, 0);    cipher.doFinal(output, len);    return output;  }  /// Generate random IV (12 bytes for GCM) using secure RNG  Uint8List _generateIV() {    return Uint8List.fromList(      List.generate(12, (_) => _secureRandom.nextInt(256)),    );  }  /// Save session to secure storage  Future<void> _saveSession(String contactId, SessionState session) async {    await _secureStorage.write(      key: 'session_$contactId',      value: jsonEncode(session.toJson()),    );  }  /// Wipe all sessions (panic wipe)  Future<void> wipeAllSessions() async {    for (final contactId in _sessions.keys) {      await _secureStorage.delete(key: 'session_$contactId');    }    _sessions.clear();    debugPrint('[Signal] All sessions wiped');  }  /// Get safety number for contact verification  String getSafetyNumber(String myPublicKey, String theirPublicKey) {    final combined = '$myPublicKey$theirPublicKey';    final digest = SHA256Digest();    final hash = Uint8List(digest.digestSize);    digest.update(        utf8.encode(combined) as Uint8List, 0, combined.length);    digest.doFinal(hash, 0);    // Return first 12 digits for display    return hash        .take(6)        .map((b) => b.toRadixString(10).padLeft(3, '0'))        .join(' ');  }}/// Session state for a contact (Double Ratchet state)./// Now with SEPARATE sending/receiving chains and skipped-key cache.class SessionState {  final String contactId;  final String rootKey;  String sendingChainKey;  String receivingChainKey;  final String senderRatchetKey;  int sendingMessageIndex;  int receivingMessageIndex;  Map<String, String> skippedMessageKeys;  final DateTime createdAt;  SessionState({    required this.contactId,    required this.rootKey,    required this.sendingChainKey,    required this.receivingChainKey,    required this.senderRatchetKey,    required this.sendingMessageIndex,    required this.receivingMessageIndex,    required this.skippedMessageKeys,    required this.createdAt,  });  factory SessionState.fromJson(Map<String, dynamic> json) => SessionState(        contactId: json['contactId'],        rootKey: json['rootKey'],        sendingChainKey: json['sendingChainKey'],        receivingChainKey: json['receivingChainKey'],        senderRatchetKey: json['senderRatchetKey'],        sendingMessageIndex: json['sendingMessageIndex'] ??            json['messageIndex'] ??            0,        receivingMessageIndex: json['receivingMessageIndex'] ?? 0,        skippedMessageKeys: Map<String, String>.from(            json['skippedMessageKeys'] ?? {}),        createdAt: DateTime.parse(json['createdAt']),      );  Map<String, dynamic> toJson() => {        'contactId': contactId,        'rootKey': rootKey,        'sendingChainKey': sendingChainKey,        'receivingChainKey': receivingChainKey,        'senderRatchetKey': senderRatchetKey,        'sendingMessageIndex': sendingMessageIndex,        'receivingMessageIndex': receivingMessageIndex,        'skippedMessageKeys': skippedMessageKeys,        'createdAt': createdAt.toIso8601String(),      };}/// Encrypted message payloadclass EncryptedPayload {  final String ciphertext;  final String iv;  final int messageIndex;  final String senderRatchetKey;  EncryptedPayload({    required this.ciphertext,    required this.iv,    required this.messageIndex,    required this.senderRatchetKey,  });  Map<String, dynamic> toJson() => {        'ciphertext': ciphertext,        'iv': iv,        'messageIndex': messageIndex,        'senderRatchetKey': senderRatchetKey,      };  factory EncryptedPayload.fromJson(Map<String, dynamic> json) =>      EncryptedPayload(        ciphertext: json['ciphertext'],        iv: json['iv'],        messageIndex: json['messageIndex'],        senderRatchetKey: json['senderRatchetKey'],      );}